#include <linux/slab.h>  // For kmalloc, vmalloc, and kfree

struct xt_table_info {
    unsigned int size;
    // Other members can be assumed to exist but are not relevant for this function.
};

struct xt_table_info *alloc_xt_table_info(unsigned int size) {
    size_t total_size = sizeof(struct xt_table_info) + size;

    if (total_size < sizeof(struct xt_table_info) || total_size < size)
        return NULL;  // Overflow check

    struct xt_table_info *table_info = kmalloc(total_size, GFP_KERNEL);
    if (!table_info) {
        table_info = vzalloc(total_size);
        if (!table_info)
            return NULL;  // Allocation failed
    }

    table_info->size = size;
    return table_info;
}

