struct xt_table_info *alloc_xt_table_info(unsigned int size)
{
    struct xt_table_info *info;
    size_t total_size = sizeof(struct xt_table_info) + size;

    if (size > (UINT_MAX - sizeof(struct xt_table_info)))
        return NULL;

    info = kmalloc(total_size, GFP_KERNEL);
    if (!info)
        info = vzalloc(total_size);

    if (!info)
        return NULL;

    info->size = size;
    return info;
}
